#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

void inspect_subsets(const vector<long long>& weights, int position,
                     long long selected_sum, long long total_sum,
                     long long& best) {
    if (position == static_cast<int>(weights.size())) {
        long long difference = total_sum - 2 * selected_sum;
        if (difference < 0) {
            difference = -difference;
        }
        best = min(best, difference);
        return;
    }

    inspect_subsets(weights, position + 1, selected_sum, total_sum, best);
    inspect_subsets(weights, position + 1,
                    selected_sum + weights[position], total_sum, best);
}

long long minimum_difference(const vector<long long>& weights) {
    long long total_sum = 0;
    for (long long weight : weights) {
        total_sum += weight;
    }
    long long best = total_sum;
    inspect_subsets(weights, 0, 0, total_sum, best);
    return best;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> weights(n);
    for (long long& weight : weights) {
        cin >> weight;
    }
    cout << minimum_difference(weights) << '\n';
    return 0;
}

